import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  BarChart,
  Bar,
  ComposedChart,
  ReferenceLine,
  Cell,
} from 'recharts';
import {
  ArrowUpRight,
  CalendarDays,
  BarChart3,
  CheckCircle,
  Download,
  Loader2,
  Lock,
  LogOut,
  PiggyBank,
