  const incomeFormCardClasses = card({
    variant: 'muted',
    padding: 'sm',
    className: 'space-y-3',
  });
  const goalFormCardClasses = card({
    variant: 'muted',
    padding: 'sm',
    className: 'mt-4 space-y-3',
